const AUTO_SLIDE_INTERVAL_MS=2500;
function startAutoSlides(root,slideSelector,interval=AUTO_SLIDE_INTERVAL_MS){
 if(!root)return ()=>{};
 const slides=[...root.querySelectorAll(slideSelector)],motion=window.matchMedia?.('(prefers-reduced-motion: reduce)');let index=0,timer;
 function prepareNext(){if(root.getBoundingClientRect().top>window.innerHeight+300)return;const image=slides[(index+1)%slides.length]?.querySelector('img');if(image)image.loading='eager'}
 function schedule(){clearInterval(timer);if(!document.hidden&&!motion?.matches&&slides.length>1)timer=setInterval(()=>{index=(index+1)%slides.length;slides.forEach((slide,i)=>slide.hidden=i!==index);prepareNext()},interval)}
 const observer=window.IntersectionObserver?new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting))prepareNext()},{rootMargin:'300px'}):null;observer?.observe(root);
 document.addEventListener('visibilitychange',schedule);motion?.addEventListener?.('change',schedule);schedule();
 return ()=>{observer?.disconnect();clearInterval(timer);document.removeEventListener('visibilitychange',schedule);motion?.removeEventListener?.('change',schedule)};
}
function initHero(){return startAutoSlides(main.querySelector('.hero-carousel'),'.hero-slide',4000)}

