const givingCurrencies={NGN:{label:'Naira',symbol:'₦',flag:'ng'},USD:{label:'US dollars',symbol:'$',flag:'us'},GBP:{label:'Pounds sterling',symbol:'£',flag:'gb'}};
function projectBank(currency){const project=window.CHURCH_PROJECT||{};return project.accounts?.[currency]||(currency==='NGN'?project:{});}
function projectDetails(currency){
 const account=projectBank(currency),valid=currency==='NGN'?/^\d{10}$/.test(account.accountNumber||''):Boolean(account.accountNumber?.trim());
 const ready=Boolean(account.bankName?.trim()&&account.accountName?.trim()&&valid),label=givingCurrencies[currency].label;
 return `<p class="giving-detail-label">${esc(label)} · Church project account</p>${ready?`<dl class="giving-bank"><div><dt>Bank</dt><dd>${esc(account.bankName)}</dd></div><div><dt>Account name</dt><dd>${esc(account.accountName)}</dd></div><div class="giving-bank-number"><dt>Account number</dt><dd class="project-account-number">${esc(account.accountNumber)}</dd></div>${['iban','swiftCode','routingNumber','bankAddress','transferInstructions'].filter(key=>account[key]).map(key=>`<div><dt>${({iban:'IBAN',swiftCode:'SWIFT / BIC',routingNumber:'Routing number',bankAddress:'Bank address',transferInstructions:'Transfer instructions'})[key]}</dt><dd>${esc(account[key])}</dd></div>`).join('')}</dl><button class="button button-gold copy-project-account" data-currency="${currency}" type="button">Copy account number ⧉</button><p class="giving-help">Confirm the account name and currency before transferring.</p>`:`<div class="giving-pending"><strong>${currency==='NGN'?'Account details coming soon.':'Give in '+esc(label)+'.'}</strong><p>Contact the church for confirmed ${esc(currency)} project account details${currency==='NGN'?'':' and international transfer instructions'}.</p><a class="giving-contact" href="tel:+2348162690858">Call Pastor Sam · 0816 269 0858 ↗</a></div>`}<p class="project-copy-status" role="status"></p>`;
}
